package policyapply

// Issue #628: the applied-policy gate against a live three-server cluster. Each test runs a throwaway in-process
// cluster of three nats-servers on 127.0.0.1, in operator mode, with every port chosen at run time (port 0, never a
// fixed one); the operator and account JWTs are generated by the test, and every server and connection is stopped at
// test end by t.Cleanup. The list sets are those of AT-010.

import (
	"context"
	"fmt"
	"testing"
	"time"

	"github.com/nats-io/jwt/v2"
)

const at010Three = 3

// newThreeEnv starts the three-server cluster holding the compiled generation 1, and its run.
func newThreeEnv(t *testing.T) (*at010Env, *at010Run) {
	t.Helper()
	if testing.Short() {
		t.Skip("live three-server cluster")
	}
	e := newLiveEnvN(t, set1(), false, at010Three)
	return e, newAT010Run(t, e)
}

// TestGateThreeServersApply: generation 2 is pushed to all three servers; the gate proves that every server holds
// the target JWT and refuses every revoked key, and reports applied.
func TestGateThreeServersApply(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()
	e, r := newThreeEnv(t)
	r.openWitnesses(ctx, e.urls)

	e.waitNewSecond()
	j2 := e.account(r.c2, r.realPub)
	e.pushTo(ctx, j2, "s1", "s2", "s3")

	gi := e.gateInput(r, r.prober, r.wit)
	gi.TargetJWT = j2
	st, err := Gate(ctx, gi)
	if err != nil {
		t.Fatal(err)
	}
	if st.State != StateApplied || !st.InForce || len(st.Failing) != 0 {
		t.Fatalf("gate: %+v", st)
	}
	if g := gens(st); len(g) != 3 || g["s1"] != "2" || g["s2"] != "2" || g["s3"] != "2" {
		t.Errorf("servers = %v", g)
	}

	// Every server holds the target JWT, with every revoked key in its revocation list.
	want, err := jwt.DecodeAccountClaims(j2)
	if err != nil {
		t.Fatal(err)
	}
	held := e.heldJWTs(ctx)
	if len(held) != 3 {
		t.Fatalf("servers answered: %d", len(held))
	}
	for n, c := range held {
		if c.ID != want.ID {
			t.Errorf("server %s does not hold the target JWT", n)
		}
		for _, k := range r.ex.RevokedKeys {
			if _, ok := c.Revocations[k]; !ok {
				t.Errorf("server %s does not revoke %s", n, k)
			}
		}
	}

	// Every probe ran on every server, and every witness is closed.
	if got, want := len(r.prober.Minted()), 3*(len(r.ex.Removed)+len(r.ex.CredentialOnly)); got != want {
		t.Errorf("probes minted = %d, want %d", got, want)
	}
	closed, _ := r.wit.Closed(ctx)
	if len(closed) != 3*len(r.c1.Users) {
		t.Errorf("witnesses = %d", len(closed))
	}
	for k, c := range closed {
		if !c {
			t.Errorf("witness %+v is open", k)
		}
	}

	// The probes are revoked at the end; the real old key is refused by each of the three servers.
	if err := r.revoke(); err != nil {
		t.Fatal(err)
	}
	e.checkProbesRevoked(ctx, r.minted())
	if len(e.urls) != 3 {
		t.Fatalf("urls = %v", e.urls)
	}
	e.refusedConnect(ctx, r.real)
}

// TestGateThreeServersOneHeldBack: s3 is down while generation 2 is pushed to s1 and s2, and restarts afterwards with
// its resolver directory still holding generation 1 (the resolver's sync interval is an hour). The gate says partial,
// names s3 and no other server, and does not report applied.
func TestGateThreeServersOneHeldBack(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()
	e, r := newThreeEnv(t)

	e.stop("s3")
	r.openWitnesses(ctx, map[string]string{"s1": e.urls["s1"], "s2": e.urls["s2"]})

	e.waitNewSecond()
	j2 := e.account(r.c2, r.realPub)
	e.pushTo(ctx, j2, "s1", "s2")

	routes := fmt.Sprintf("nats-route://127.0.0.1:%d", e.srvs["s1"].ClusterAddr().Port)
	e.start("s3", false, routes)
	e.waitRoutes()
	e.waitServers(ctx)
	// A connection to s3 before it takes the change: it loads the account from s3's own directory.
	r.openWitnesses(ctx, map[string]string{"s3": e.urls["s3"]})

	st, err := Gate(ctx, e.gateInput(r, r.prober, r.wit))
	if err != nil {
		t.Fatal(err)
	}
	if st.State != StatePartial || st.InForce {
		t.Fatalf("held back: %+v", st)
	}
	if g := gens(st); len(g) != 3 || g["s1"] != "2" || g["s2"] != "2" || g["s3"] != "1" {
		t.Fatalf("servers = %v (s3 must still hold the previous generation)", g)
	}
	if len(st.Failing) == 0 {
		t.Fatal("no failure")
	}
	for _, f := range st.Failing {
		if f.Server != "s3" {
			t.Errorf("failure names %q, want only s3: %+v", f.Server, f)
		}
	}
	if !hasFailure(st, "s3", "", CheckGeneration) || !hasFailure(st, "s3", "", CheckRevoked) {
		t.Errorf("failing = %+v", st.Failing)
	}
	if err := r.revoke(); err != nil {
		t.Fatal(err)
	}
}

// TestGateThreeServersDeclaredCount: the operator declares three servers but only two answer (s3 is stopped). The gate
// refuses: the server set is not complete, so nothing is proven and nothing is reported applied.
func TestGateThreeServersDeclaredCount(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()
	e, r := newThreeEnv(t)
	e.stop("s3")
	r.openWitnesses(ctx, e.urls)

	e.waitNewSecond()
	j2 := e.account(r.c2, r.realPub)
	e.pushTo(ctx, j2, "s1", "s2")

	set, err := e.cluster.Servers(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(set.Names) != 2 || set.Complete(3) {
		t.Fatalf("server set = %+v: two servers answer, so a declared count of 3 is not complete", set)
	}

	gi := e.gateInput(r, r.prober, r.wit)
	if gi.Inventory != 3 {
		t.Fatalf("declared count = %d, want 3", gi.Inventory)
	}
	st, err := Gate(ctx, gi)
	if err != nil {
		t.Fatal(err)
	}
	if st.State == StateApplied || st.InForce {
		t.Fatalf("gate reported success with a server missing: %+v", st)
	}
	if st.State != StatePartial || !hasFailure(st, "", "", CheckServerSet) {
		t.Fatalf("gate: %+v", st)
	}
	if len(st.Failing) != 1 || st.Failing[0].Detail != set.Why(3) {
		t.Errorf("failing = %+v, want the server set failure alone", st.Failing)
	}
	// Nothing was proven: no server is reported on any generation and no probe ran.
	if len(st.Servers) != 0 {
		t.Errorf("servers reported: %+v", st.Servers)
	}
	if n := len(r.prober.Minted()); n != 0 {
		t.Errorf("%d probes minted on an incomplete server set", n)
	}
	if err := r.revoke(); err != nil {
		t.Fatal(err)
	}
}
